from rich.pretty import _ipy_display_hook
from rich.console import Console
import io

def _ipy_display_hook_fixed(value, console=None):
    if console is None:
        console = Console(file=io.StringIO(), force_jupyter=True)
    console.begin_capture()
    if hasattr(value, "__rich_console__"):
        pass
    else:
        from rich.pretty import Pretty
        value = Pretty(value)
    console.print(value, end="")
    result = console.capture.get()
    if result.endswith("\n"):
        result = result[:-1]
    return result

class Thing1:
    def __repr__(self) -> str:
        return "hello"

class Thing2:
    def __repr__(self) -> str:
        return "hello\n"

console = Console(file=io.StringIO(), force_jupyter=True)
print(f"Thing1: {repr(_ipy_display_hook_fixed(Thing1(), console=console))}")
print(f"Thing2: {repr(_ipy_display_hook_fixed(Thing2(), console=console))}")
